    26→export const EditTool = Tool.define("edit", {
    27→  description: DESCRIPTION,
    28→  parameters: z.object({
    29→    filePath: z.string().describe("The absolute path to the file to modify"),
    30→    oldString: z.string().describe("The text to replace"),
    31→    newString: z.string().describe("The text to replace it with (must be different from oldString)"),
    32→    replaceAll: z.boolean().optional().describe("Replace all occurrences of oldString (default false)"),
    33→  }),
    34→  async execute(params, ctx) {
