    71→            return result
    72→          }
    73→          const truncated = await Truncate.output(result.output, {}, initCtx?.agent)
    74→          return {
    75→            ...result,
    76→            output: truncated.content,
    77→            metadata: {
    78→              ...result.metadata,
    79→              truncated: truncated.truncated,
    80→              ...(truncated.truncated && { outputPath: truncated.outputPath }),
    81→            },
    82→          }
    83→        }
    84→        return toolInfo
    85→      },
    86→    }
    87→  }
    88→}
