if (isImage || isPdf) {
  return {
    attachments: [{
      type: "file",
      mime,
      url: `data:${mime};base64,${Buffer.from(await file.bytes()).toString("base64")}`,
    }],
  }
}

// 二进制文件检测
async function isBinaryFile(filepath: string, file: Bun.BunFile): Promise<boolean> {
  // 1. 检查文件扩展名（.zip, .exe 等）
  // 2. 检查前 4096 字节中的 null 字符
  // 3. 检查非打印字符比例（>30% 视为二进制）
