   118→        diagnostics: {},
   119→      },
   120→    })
   121→
   122→    let output = "Edit applied successfully."
   123→    await LSP.touchFile(filePath, true)
   124→    const diagnostics = await LSP.diagnostics()
   125→    const normalizedFilePath = Filesystem.normalizePath(filePath)
   126→    const issues = diagnostics[normalizedFilePath] ?? []
   127→    const errors = issues.filter((item) => item.severity === 1)
   128→    if (errors.length > 0) {
   129→      const limited = errors.slice(0, MAX_DIAGNOSTICS_PER_FILE)
   130→      const suffix =
   131→        errors.length > MAX_DIAGNOSTICS_PER_FILE ? `\n... and ${errors.length - MAX_DIAGNOSTICS_PER_FILE} more` : ""
   132→      output += `\n\nLSP errors detected in this file:\n<diagnostics file="${filePath}">\n${limited.map(LSP.Diagnostic.pretty).join("\n")}${suffix}\n</diagnostics>`
   133→    }
   134→
   135→    return {
   136→      metadata: {
   137→        diagnostics,
