## 自定义工具开发

### 方式一：配置目录工具

在项目 `.opencode/tool/` 或 `~/.config/opencode/tool/` 下创建工具文件：

```typescript
// .opencode/tool/mytool.ts
import { tool } from "@opencode-ai/plugin"

export default tool({
  description: "我的自定义工具",
  args: {
    input: tool.schema.string().describe("输入参数"),
  },
  async execute(args, ctx) {
    // 请求权限（可选）
    await ctx.ask({
      permission: "mytool",
   patterns: [args.input],
      always: ["*"],
      metadata: {},
    })

    // 执行逻辑
    return `处理结果: ${args.input}`
},
})
```

