   345→      if (k < endLine) {
   346→        matchEndIndex += 1
   347→      }
   348→    }
   349→    yield content.substring(matchStartIndex, matchEndIndex)
   350→  }
   351→}
   352→
   353→export const WhitespaceNormalizedReplacer: Replacer = function* (content, find) {
   354→  const normalizeWhitespace = (text: string) => text.replace(/\s+/g, " ").trim()
   355→  const normalizedFind = normalizeWhitespace(find)
   356→
   357→  // Handle single line matches
   358→  const lines = content.split("\n")
   359→  for (let i = 0; i < lines.length; i++) {
   360→    const line = lines[i]
   361→    if (normalizeWhitespace(line) === normalizedFind) {
   362→      yield line
   363→    } else {
   364→      // Only check for substring matches if the full line doesn't match
   365→      const normalizedLine = normalizeWhitespace(line)
   366→      if (normalizedLine.includes(normalizedFind)) {
   367→        // Find the actual substring in the original line that matches
   368→        const words = find.trim().split(/\s+/)
   369→        if (words.length > 0) {
   370→          const pattern = words.map((word) => word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("\\s+")
   371→          try {
   372→            const regex = new RegExp(pattern)
   373→            const match = line.match(regex)
   374→            if (match) {
   375→              yield match[0]
   376→            }
   377→          } catch (e) {
   378→            // Invalid regex pattern, skip
   379→          }
   380→        }
   381→      }
   382→    }
   383→  }
   384→
   385→  // Handle multi-line matches
   386→  const findLines = find.split("\n")
   387→  if (findLines.length > 1) {
   388→    for (let i = 0; i <= lines.length - findLines.length; i++) {
   389→      const block = lines.slice(i, i + findLines.length)
   390→      if (normalizeWhitespace(block.join("\n")) === normalizedFind) {
   391→        yield block.join("\n")
   392→      }
   393→    }
   394→  }
   395→}
   396→
   397→export const IndentationFlexibleReplacer: Replacer = function* (content, find) {
   398→  const removeIndentation = (text: string) => {
   399→    const lines = text.split("\n")
   400→    const nonEmptyLines = lines.filter((line) => line.trim().length > 0)
   401→    if (nonEmptyLines.length === 0) return text
   402→
   403→    const minIndent = Math.min(
   404→      ...nonEmptyLines.map((line) => {
   405→        const match = line.match(/^(\s*)/)
   406→        return match ? match[1].length : 0
   407→      }),
   408→    )
   409→
   410→    return lines.map((line) => (line.trim().length === 0 ? line : line.slice(minIndent))).join("\n")
   411→  }
   412→
   413→  const normalizedFind = removeIndentation(find)
   414→  const contentLines = content.split("\n")
   415→  const findLines = find.split("\n")
   416→
   417→  for (let i = 0; i <= contentLines.length - findLines.length; i++) {
   418→    const block = contentLines.slice(i, i + findLines.length).join("\n")
   419→    if (removeIndentation(block) === normalizedFind) {
   420→      yield block
   421→    }
   422→  }
   423→}
   424→
   425→export const EscapeNormalizedReplacer: Replacer = function* (content, find) {
   426→  const unescapeString = (str: string): string => {
   427→    return str.replace(/\\(n|t|r|'|"|`|\\|\n|\$)/g, (match, capturedChar) => {
   428→      switch (capturedChar) {
   429→        case "n":
   430→          return "\n"
   431→        case "t":
   432→          return "\t"
   433→        case "r":
   434→          return "\r"
   435→        case "'":
   436→          return "'"
   437→        case '"':
   438→          return '"'
   439→        case "`":
   440→          return "`"
   441→        case "\\":
   442→          return "\\"
   443→        case "\n":
   444→          return "\n"
   445→        case "$":
   446→          return "$"
   447→        default:
   448→          return match
   449→      }
   450→    })
   451→  }
   452→
   453→  const unescapedFind = unescapeString(find)
   454→
   455→  // Try direct match with unescaped find string
   456→  if (content.includes(unescapedFind)) {
   457→    yield unescapedFind
   458→  }
   459→
   460→  // Also try finding escaped versions in content that match unescaped find
   461→  const lines = content.split("\n")
   462→  const findLines = unescapedFind.split("\n")
   463→
   464→  for (let i = 0; i <= lines.length - findLines.length; i++) {
   465→    const block = lines.slice(i, i + findLines.length).join("\n")
   466→    const unescapedBlock = unescapeString(block)
   467→
   468→    if (unescapedBlock === unescapedFind) {
   469→      yield block
   470→    }
   471→  }
   472→}
   473→
   474→export const MultiOccurrenceReplacer: Replacer = function* (content, find) {
   475→  // This replacer yields all exact matches, allowing the replace function
   476→  // to handle multiple occurrences based on replaceAll parameter
   477→  let startIndex = 0
   478→
   479→  while (true) {
   480→    const index = content.indexOf(find, startIndex)
   481→    if (index === -1) break
   482→
   483→    yield find
   484→    startIndex = index + find.length
   485→  }
   486→}
   487→
   488→export const TrimmedBoundaryReplacer: Replacer = function* (content, find) {
   489→  const trimmedFind = find.trim()
   490→
   491→  if (trimmedFind === find) {
   492→    // Already trimmed, no point in trying
   493→    return
   494→  }
   495→
   496→  // Try to find the trimmed version
   497→  if (content.includes(trimmedFind)) {
   498→    yield trimmedFind
   499→  }
   500→
   501→  // Also try finding blocks where trimmed content matches
   502→  const lines = content.split("\n")
   503→  const findLines = find.split("\n")
   504→
   505→  for (let i = 0; i <= lines.length - findLines.length; i++) {
   506→    const block = lines.slice(i, i + findLines.length).join("\n")
   507→
   508→    if (block.trim() === trimmedFind) {
   509→      yield block
   510→    }
   511→  }
   512→}
   513→
   514→export const ContextAwareReplacer: Replacer = function* (content, find) {
   515→  const findLines = find.split("\n")
   516→  if (findLines.length < 3) {
   517→    // Need at least 3 lines to have meaningful context
   518→    return
   519→  }
   520→
   521→  // Remove trailing empty line if present
   522→  if (findLines[findLines.length - 1] === "") {
   523→    findLines.pop()
   524→  }
   525→
   526→  const contentLines = content.split("\n")
   527→
   528→  // Extract first and last lines as context anchors
   529→  const firstLine = findLines[0].trim()
   530→  const lastLine = findLines[findLines.length - 1].trim()
   531→
   532→  // Find blocks that start and end with the context anchors
   533→  for (let i = 0; i < contentLines.length; i++) {
   534→    if (contentLines[i].trim() !== firstLine) continue
   535→
   536→    // Look for the matching last line
   537→    for (let j = i + 2; j < contentLines.length; j++) {
   538→      if (contentLines[j].trim() === lastLine) {
   539→        // Found a potential context block
   540→        const blockLines = contentLines.slice(i, j + 1)
   541→        const block = blockLines.join("\n")
   542→
   543→        // Check if the middle content has reasonable similarity
   544→        // (simple heuristic: at least 50% of non-empty lines should match when trimmed)
   545→        if (blockLines.length === findLines.length) {
   546→          let matchingLines = 0
   547→          let totalNonEmptyLines = 0
   548→
   549→          for (let k = 1; k < blockLines.length - 1; k++) {
   550→            const blockLine = blockLines[k].trim()
   551→            const findLine = findLines[k].trim()
   552→
   553→            if (blockLine.length > 0 || findLine.length > 0) {
   554→              totalNonEmptyLines++
   555→              if (blockLine === findLine) {
   556→                matchingLines++
   557→              }
   558→            }
   559→          }
   560→
   561→          if (totalNonEmptyLines === 0 || matchingLines / totalNonEmptyLines >= 0.5) {
   562→            yield block
   563→            break // Only match the first occurrence
   564→          }
   565→        }
   566→        break
   567→      }
   568→    }
   569→  }
   570→}
   571→
   572→export function trimDiff(diff: string): string {
   573→  const lines = diff.split("\n")
   574→  const contentLines = lines.filter(
   575→    (line) =>
   576→      (line.startsWith("+") || line.startsWith("-") || line.startsWith(" ")) &&
   577→      !line.startsWith("---") &&
   578→      !line.startsWith("+++"),
   579→  )
   580→
   581→  if (contentLines.length === 0) return diff
   582→
   583→  let min = Infinity
   584→  for (const line of contentLines) {
   585→    const content = line.slice(1)
   586→    if (content.trim().length > 0) {
   587→      const match = content.match(/^(\s*)/)
   588→      if (match) min = Math.min(min, match[1].length)
   589→    }
   590→  }
   591→  if (min === Infinity || min === 0) return diff
   592→  const trimmedLines = lines.map((line) => {
   593→    if (
   594→      (line.startsWith("+") || line.startsWith("-") || line.startsWith(" ")) &&
   595→      !line.startsWith("---") &&
   596→      !line.startsWith("+++")
   597→    ) {
   598→      const prefix = line[0]
   599→      const content = line.slice(1)
   600→      return prefix + content.slice(min)
   601→    }
   602→    return line
   603→  })
   604→
   605→  return trimmedLines.join("\n")
   606→}
   607→
   608→export function replace(content: string, oldString: string, newString: string, replaceAll = false): string {
   609→  if (oldString === newString) {
   610→    throw new Error("oldString and newString must be different")
   611→  }
   612→
   613→  let notFound = true
   614→
   615→  for (const replacer of [
   616→    SimpleReplacer,
   617→    LineTrimmedReplacer,
   618→    BlockAnchorReplacer,
   619→    WhitespaceNormalizedReplacer,
   620→    IndentationFlexibleReplacer,
   621→    EscapeNormalizedReplacer,
   622→    TrimmedBoundaryReplacer,
   623→    ContextAwareReplacer,
   624→    MultiOccurrenceReplacer,
   625→  ]) {
   626→    for (const search of replacer(content, oldString)) {
   627→      const index = content.indexOf(search)
   628→      if (index === -1) continue
   629→      notFound = false
   630→      if (replaceAll) {
   631→        return content.replaceAll(search, newString)
   632→      }
   633→      const lastIndex = content.lastIndexOf(search)
   634→      if (index !== lastIndex) continue
   635→      return content.substring(0, index) + newString + content.substring(index + search.length)
   636→    }
   637→  }
   638→
   639→  if (notFound) {
   640→    throw new Error("oldString not found in content")
   641→  }
   642→  throw new Error(
   643→    "Found multiple matches for oldString. Provide more surrounding lines in oldString to identify the correct match.",
   644→  )
   645→}
