   218→export const BlockAnchorReplacer: Replacer = function* (content, find) {
   219→  const originalLines = content.split("\n")
   220→  const searchLines = find.split("\n")
   221→
   222→  if (searchLines.length < 3) {
   223→    return
   224→  }
   225→
   226→  if (searchLines[searchLines.length - 1] === "") {
   227→    searchLines.pop()
   228→  }
   229→
   230→  const firstLineSearch = searchLines[0].trim()
   231→  const lastLineSearch = searchLines[searchLines.length - 1].trim()
   232→  const searchBlockSize = searchLines.length
   233→
   234→  // Collect all candidate positions where both anchors match
   235→  const candidates: Array<{ startLine: number; endLine: number }> = []
   236→  for (let i = 0; i < originalLines.length; i++) {
   237→    if (originalLines[i].trim() !== firstLineSearch) {
   238→      continue
   239→    }
   240→
   241→    // Look for the matching last line after this first line
   242→    for (let j = i + 2; j < originalLines.length; j++) {
   243→      if (originalLines[j].trim() === lastLineSearch) {
   244→        candidates.push({ startLine: i, endLine: j })
   245→        break // Only match the first occurrence of the last line
   246→      }
   247→    }
   248→  }
   249→
   250→  // Return immediately if no candidates
   251→  if (candidates.length === 0) {
   252→    return
   253→  }
   254→
   255→  // Handle single candidate scenario (using relaxed threshold)
   256→  if (candidates.length === 1) {
   257→    const { startLine, endLine } = candidates[0]
   258→    const actualBlockSize = endLine - startLine + 1
   259→
