## 自定义工具开发

### 方式一：配置目录工具

在项目 `.opencode/tool/` 或 `~/.config/opencode/tool/` 下创建工具文件：

```typescript
// .opencode/tool/mytool.ts
import { tool } from "@opencode-ai/plugin"

export default tool({
  description: "我的自定义工具",
  args: {
    input: tool.schema.string().describe("输入参数"),
  },
  async execute(args, ctx) {
    // 请求权限（可选）
    await ctx.ask({
      permission: "mytool",
   patterns: [args.input],
      always: ["*"],
      metadata: {},
    })

    // 执行逻辑
    return `处理结果: ${args.input}`
},
})
```

### 方式二：插件工具

```typescript
// my-plugin.ts
import type { Plugin } from "@opencode-ai/plugin"

const plugin: Plugin = async (input) => {
  return {
    tool: {
      "my-tool": {
        description: "插件工具",
        args: {
          param: input.$.z.string(),
        },
    async execute(args, ctx) {
  return `结果: ${args.param}`
        },
      },
    },
  }
}

export default plugin
```

### ToolContext API

```typescript
interface ToolContext {
  sessionID: string
  messageID: string
  agent: string
  abort: AbortSignal

  // 更新工具状态（实时反馈给 UI）
  metadata(input: { title?: string; metadata?: any }): void

  // 请求用户授权
  ask(input: {
    permission: string      // 权限类型
    patterns: string[]      // 操作模式
    always: string[]        // "始终允许"的模式
    metadata: any     // 展示信息
  }): Promise<void>
}
```

