   218→export const BlockAnchorReplacer: Replacer = function* (content, find) {
   219→  const originalLines = content.split("\n")
   220→  const searchLines = find.split("\n")
   221→
   222→  if (searchLines.length < 3) {
   223→    return
   224→  }
   225→
   226→  if (searchLines[searchLines.length - 1] === "") {
   227→    searchLines.pop()
   228→  }
   229→
   230→  const firstLineSearch = searchLines[0].trim()
   231→  const lastLineSearch = searchLines[searchLines.length - 1].trim()
   232→  const searchBlockSize = searchLines.length
   233→
   234→  // Collect all candidate positions where both anchors match
   235→  const candidates: Array<{ startLine: number; endLine: number }> = []
   236→  for (let i = 0; i < originalLines.length; i++) {
   237→    if (originalLines[i].trim() !== firstLineSearch) {
   238→      continue
   239→    }
   240→
   241→    // Look for the matching last line after this first line
   242→    for (let j = i + 2; j < originalLines.length; j++) {
   243→      if (originalLines[j].trim() === lastLineSearch) {
   244→        candidates.push({ startLine: i, endLine: j })
   245→        break // Only match the first occurrence of the last line
   246→      }
   247→    }
   248→  }
   249→
   250→  // Return immediately if no candidates
   251→  if (candidates.length === 0) {
   252→    return
   253→  }
   254→
   255→  // Handle single candidate scenario (using relaxed threshold)
   256→  if (candidates.length === 1) {
   257→    const { startLine, endLine } = candidates[0]
   258→    const actualBlockSize = endLine - startLine + 1
   259→
   260→    let similarity = 0
   261→    let linesToCheck = Math.min(searchBlockSize - 2, actualBlockSize - 2) // Middle lines only
   262→
   263→    if (linesToCheck > 0) {
   264→      for (let j = 1; j < searchBlockSize - 1 && j < actualBlockSize - 1; j++) {
   265→        const originalLine = originalLines[startLine + j].trim()
   266→        const searchLine = searchLines[j].trim()
   267→        const maxLen = Math.max(originalLine.length, searchLine.length)
   268→        if (maxLen === 0) {
   269→          continue
   270→        }
   271→        const distance = levenshtein(originalLine, searchLine)
   272→        similarity += (1 - distance / maxLen) / linesToCheck
   273→
   274→        // Exit early when threshold is reached
   275→        if (similarity >= SINGLE_CANDIDATE_SIMILARITY_THRESHOLD) {
   276→          break
   277→        }
   278→      }
   279→    } else {
   280→      // No middle lines to compare, just accept based on anchors
   281→      similarity = 1.0
   282→    }
   283→
   284→    if (similarity >= SINGLE_CANDIDATE_SIMILARITY_THRESHOLD) {
   285→      let matchStartIndex = 0
   286→      for (let k = 0; k < startLine; k++) {
   287→        matchStartIndex += originalLines[k].length + 1
   288→      }
   289→      let matchEndIndex = matchStartIndex
   290→      for (let k = startLine; k <= endLine; k++) {
   291→        matchEndIndex += originalLines[k].length
   292→        if (k < endLine) {
   293→          matchEndIndex += 1 // Add newline character except for the last line
   294→        }
   295→      }
   296→      yield content.substring(matchStartIndex, matchEndIndex)
   297→    }
   298→    return
   299→  }
   300→
   301→  // Calculate similarity for multiple candidates
   302→  let bestMatch: { startLine: number; endLine: number } | null = null
   303→  let maxSimilarity = -1
   304→
   305→  for (const candidate of candidates) {
   306→    const { startLine, endLine } = candidate
   307→    const actualBlockSize = endLine - startLine + 1
   308→
   309→    let similarity = 0
   310→    let linesToCheck = Math.min(searchBlockSize - 2, actualBlockSize - 2) // Middle lines only
   311→
   312→    if (linesToCheck > 0) {
   313→      for (let j = 1; j < searchBlockSize - 1 && j < actualBlockSize - 1; j++) {
   314→        const originalLine = originalLines[startLine + j].trim()
   315→        const searchLine = searchLines[j].trim()
   316→        const maxLen = Math.max(originalLine.length, searchLine.length)
   317→        if (maxLen === 0) {
   318→          continue
   319→        }
   320→        const distance = levenshtein(originalLine, searchLine)
   321→        similarity += 1 - distance / maxLen
   322→      }
   323→      similarity /= linesToCheck // Average similarity
   324→    } else {
   325→      // No middle lines to compare, just accept based on anchors
   326→      similarity = 1.0
   327→    }
   328→
   329→    if (similarity > maxSimilarity) {
   330→      maxSimilarity = similarity
   331→      bestMatch = candidate
   332→    }
   333→  }
   334→
   335→  // Threshold judgment
   336→  if (maxSimilarity >= MULTIPLE_CANDIDATES_SIMILARITY_THRESHOLD && bestMatch) {
   337→    const { startLine, endLine } = bestMatch
   338→    let matchStartIndex = 0
   339→    for (let k = 0; k < startLine; k++) {
   340→      matchStartIndex += originalLines[k].length + 1
   341→    }
   342→    let matchEndIndex = matchStartIndex
   343→    for (let k = startLine; k <= endLine; k++) {
   344→      matchEndIndex += originalLines[k].length
   345→      if (k < endLine) {
   346→        matchEndIndex += 1
   347→      }
   348→    }
   349→    yield content.substring(matchStartIndex, matchEndIndex)
   350→  }
   351→}
