   147→export type Replacer = (content: string, find: string) => Generator<string, void, unknown>
   148→
   149→// Similarity thresholds for block anchor fallback matching
   150→const SINGLE_CANDIDATE_SIMILARITY_THRESHOLD = 0.0
   151→const MULTIPLE_CANDIDATES_SIMILARITY_THRESHOLD = 0.3
   152→
   153→/**
   154→ * Levenshtein distance algorithm implementation
   155→ */
   156→function levenshtein(a: string, b: string): number {
   157→  // Handle empty strings
   158→  if (a === "" || b === "") {
   159→    return Math.max(a.length, b.length)
   160→  }
   161→  const matrix = Array.from({ length: a.length + 1 }, (_, i) =>
   162→    Array.from({ length: b.length + 1 }, (_, j) => (i === 0 ? j : j === 0 ? i : 0)),
   163→  )
   164→
   165→  for (let i = 1; i <= a.length; i++) {
   166→    for (let j = 1; j <= b.length; j++) {
   167→      const cost = a[i - 1] === b[j - 1] ? 0 : 1
   168→      matrix[i][j] = Math.min(matrix[i - 1][j] + 1, matrix[i][j - 1] + 1, matrix[i - 1][j - 1] + cost)
   169→    }
   170→  }
   171→  return matrix[a.length][b.length]
   172→}
   173→
   174→export const SimpleReplacer: Replacer = function* (_content, find) {
   175→  yield find
   176→}
