   178→export const LineTrimmedReplacer: Replacer = function* (content, find) {
   179→  const originalLines = content.split("\n")
   180→  const searchLines = find.split("\n")
   181→
   182→  if (searchLines[searchLines.length - 1] === "") {
   183→    searchLines.pop()
   184→  }
   185→
   186→  for (let i = 0; i <= originalLines.length - searchLines.length; i++) {
   187→    let matches = true
   188→
   189→    for (let j = 0; j < searchLines.length; j++) {
   190→      const originalTrimmed = originalLines[i + j].trim()
   191→      const searchTrimmed = searchLines[j].trim()
   192→
   193→      if (originalTrimmed !== searchTrimmed) {
   194→        matches = false
   195→        break
   196→      }
   197→    }
   198→
   199→    if (matches) {
   200→      let matchStartIndex = 0
   201→      for (let k = 0; k < i; k++) {
   202→        matchStartIndex += originalLines[k].length + 1
   203→      }
   204→
   205→      let matchEndIndex = matchStartIndex
   206→      for (let k = 0; k < searchLines.length; k++) {
   207→        matchEndIndex += originalLines[i + k].length
   208→        if (k < searchLines.length - 1) {
   209→          matchEndIndex += 1 // Add newline character except for the last line
   210→        }
   211→      }
   212→
   213→      yield content.substring(matchStartIndex, matchEndIndex)
   214→    }
   215→  }
   216→}
