    }],
  }
}

// 二进制文件检测
async function isBinaryFile(filepath: string, file: Bun.BunFile): Promise<boolean> {
  // 1. 检查文件扩展名（.zip, .exe 等）
  // 2. 检查前 4096 字节中的 null 字符
  // 3. 检查非打印字符比例（>30% 视为二进制）
}

// 输出格式
// 00001| 第一行内容
// 00002| 第二行内容
```

### TaskTool - 子 Agent 任务

**文件**: `packages/opencode/src/tool/task.ts`

**核心特性**:
- 创建子会话执行复杂任务
- 支持不同类型的子 Agent
- 实时同步工具调用状态

```typescript
